// §10.3 Node 3: Calculate pricing breakdown (JavaScript)
// Never stacks multiple rules — applies the single best match.

const products = $('Fetch Products for Bulk').all().map(i => i.json);
const discount  = $('Fetch Discount Rule').first()?.json ?? null;
const parentCtx = $input.first()?.json ?? {};

const quantity  = parentCtx.entities?.quantity ?? 1;
const product   = products[0]; // primary match

if (!product) {
  return [{
    json: {
      ...parentCtx,
      pricingError:  true,
      products_json: JSON.stringify([]),
      discount_json: JSON.stringify(discount),
      pricing_json:  JSON.stringify(null)
    }
  }];
}

if (product.stock < quantity) {
  return [{
    json: {
      ...parentCtx,
      pricingError:  true,
      stockError:    true,
      products_json: JSON.stringify([product]),
      discount_json: 'null',
      pricing_json:  JSON.stringify({
        error: `Requested ${quantity}, but only ${product.stock} available in stock.`
      })
    }
  }];
}

const unitPrice  = parseFloat(product.price);
const subtotal   = unitPrice * quantity;

let discountAmount = 0;
let finalTotal     = subtotal;
let discountLabel  = 'No discount';

if (discount) {
  if (discount.discount_type === 'percentage') {
    discountAmount = subtotal * (parseFloat(discount.discount_value) / 100);
    finalTotal     = subtotal - discountAmount;
    discountLabel  = `${discount.discount_value}% off`;
  } else if (discount.discount_type === 'fixed_price') {
    // fixed_price overrides unit price per item
    const fixedUnitPrice = parseFloat(discount.discount_value);
    finalTotal           = fixedUnitPrice * quantity;
    discountAmount       = subtotal - finalTotal;
    discountLabel        = `$${discount.discount_value}/item (special price)`;
  }
}

const pricing = {
  product_name:    product.name,
  unit_price:      unitPrice.toFixed(2),
  quantity,
  subtotal:        subtotal.toFixed(2),
  discount_label:  discountLabel,
  discount_amount: discountAmount.toFixed(2),
  final_total:     finalTotal.toFixed(2),
  currency:        'USD'
};

return [{
  json: {
    ...parentCtx,
    pricingError:  false,
    products_json: JSON.stringify(products),
    discount_json: JSON.stringify(discount ?? {}),
    pricing_json:  JSON.stringify(pricing)
  }
}];

const aiText = $input.item.json.candidates?.[0]?.content?.parts?.[0]?.text ?? $input.item.json.candidates?.[0]?.content?.parts?.[0]?.text ?? '';
const ctx     = $('Calculate Bulk Pricing').item.json;

return [{
  json: {
    replyText:   aiText.trim(),
    chatId:      ctx.chatId,
    business_id: ctx.business_id,
    phoneNumber: ctx.phoneNumber,
    pricing_json: ctx.pricing_json
  }
}];
